import { ImageResponse } from "next/og";

// Generated from brand/make_brand.py (tensorphysics-og.svg). The official artwork is an outlined SVG,
// rendered to PNG at build time so the repository stays text-only.
export const alt = "TensorPhysics: know where your simulation breaks before you cut metal.";
export const size = { width: 1200, height: 630 };
export const contentType = "image/png";

const SVG = "data:image/svg+xml;base64,";

export default function Image() {
  return new ImageResponse(
    (
      <img src={SVG} width={1200} height={630} alt="" />
    ),
    size,
  );
}
